function fresh(){return {version:1,event:{id:crypto.randomUUID(),name:'Pernikahan Anda',date:''},guests:[],logs:[],pin:null,guestEpoch:0};}
function validate(d){if(!d||d.version!==1||!d.event||typeof d.event.id!=='string'||typeof d.event.name!=='string'||typeof d.event.date!=='string'||!Array.isArray(d.guests)||!Array.isArray(d.logs)||d.guests.length>20000)throw Error('Format data tidak sesuai.');if(!Number.isInteger(d.guestEpoch??0)||(d.guestEpoch??0)<0)throw Error('Versi daftar tamu tidak valid.');if(d.event.invitationText!==undefined&&(typeof d.event.invitationText!=='string'||d.event.invitationText.length>2000))throw Error('Teks undangan maksimal 2.000 karakter.');const ids=new Set(),codes=new Set();for(const g of d.guests){if(typeof g.id!=='string'||typeof g.code!=='string'||typeof g.name!=='string'||!g.name.trim()||typeof g.group!=='string'||typeof g.active!=='boolean'||!Number.isInteger(g.quota)||g.quota<1||g.quota>1000||!Number.isInteger(g.arrived)||g.arrived<0||g.arrived>g.quota||ids.has(g.id)||codes.has(g.code))throw Error('Data tamu tidak valid.');if(g.akad!==undefined&&!['y','n'].includes(g.akad))throw Error('Pilihan akad harus y atau n.');if(g.vip!==undefined&&!['y','n'].includes(g.vip))throw Error('Pilihan VIP harus y atau n.');for(const key of ['whatsappOpenedAt','whatsappSentAt'])if(g[key]!=null&&(typeof g[key]!=='string'||g[key].length>64||isNaN(Date.parse(g[key]))))throw Error('Tanggal WhatsApp tidak valid.');if(g.phone!==undefined&&(typeof g.phone!=='string'||(g.phone!==''&&!/^[1-9]\d{7,14}$/.test(g.phone))))throw Error('Nomor WhatsApp tidak valid.');if(g.deleted!==undefined&&(typeof g.deleted!=='boolean'||(g.deleted&&(g.active||g.name!=='Tamu dihapus'||g.phone||g.group))))throw Error('Tamu yang dihapus tidak valid.');ids.add(g.id);codes.add(g.code);}for(const l of d.logs)if(typeof l.id!=='string'||!ids.has(l.guest)||!Number.isInteger(l.count)||typeof l.at!=='string'||isNaN(Date.parse(l.at)))throw Error('Riwayat tidak valid.');if(d.pin!==null&&typeof d.pin!=='string')throw Error('PIN tidak valid.');return d;}
function displayEventName(name){return String(name||'').replaceAll('Cesar & Revalina','Reva & Cesar').replaceAll('Cesar dan Revalina','Reva dan Cesar');}
db=fresh();readFailed=true;
async function commit(change){if(readFailed)throw Error('Database belum siap. Muat ulang atau pulihkan cadangan.');const record=await TemuStore.mutate(change,validate);db=record.state;render();refreshSyncStatus(record);scheduleSync();}
