$('#delete-event').onclick=async()=>{if(!await admin())return;const record=await TemuStore.read();if(!record.config.enabled||!record.config.token)return toast('Hubungkan server sebelum menghapus acara.');await syncNow();const current=await TemuStore.read();if(current.outbox.length||current.conflicts.some(x=>!x.resolved))return toast('Selesaikan sinkronisasi dan konflik terlebih dahulu.');const eventId=db.event.id,eventName=db.event.name;modal('Hapus acara',`<p>Seluruh tamu, QR, akses undangan, foto, video, dan cadangan otomatis acara <strong>${esc(eventName)}</strong> akan dihapus dari layanan. Tindakan ini tidak dapat dibatalkan.</p><label>Ketik nama acara untuk melanjutkan<input id="confirm-event-name" autocomplete="off"></label><button id="confirm-delete-event" class="danger">Hapus acara dan seluruh data</button>`);$('#confirm-delete-event').onclick=async()=>{if($('#confirm-event-name').value!==eventName)return toast('Nama acara belum cocok.');if(db.event.id!==eventId)return toast('Acara berubah. Buka kembali pengaturan.');try{const response=await fetch('/api/events/'+encodeURIComponent(eventId),{method:'DELETE',headers:{'Authorization':'Bearer '+current.config.token,'X-Temu-Delete':'1'},cache:'no-store',signal:AbortSignal.timeout(15000)});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Acara belum dapat dihapus.');const reset=await TemuStore.clearEvent(fresh(),validate);db=reset.state;unlocked=true;refreshSyncStatus(reset);render();$('#modal').close();page('pengaturan');toast('Acara dan data tamu telah dihapus.');}catch(error){toast(error.name==='TimeoutError'?'Server belum terjangkau. Coba lagi saat online.':error.message);}};};
$('#set-pin').onclick=async()=>{if(!await admin())return;const p=$('#new-pin').value;if(!/^\d{4,12}$/.test(p))return toast('PIN harus terdiri dari 4–12 angka.');const digest=await hash(db.event.id+':'+p);await commit(d=>d.pin=digest);$('#new-pin').value='';toast('PIN tersimpan.');};$('#lock').onclick=()=>{if(!db.pin)return toast('Simpan PIN terlebih dahulu.');unlocked=false;page('pindai');toast('Mode petugas aktif.');};
function csvRows(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Tanda kutip CSV tidak lengkap.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
$('#export-csv').onclick=async()=>{if(!await admin())return;const quote=x=>'"'+String(x).replace(/"/g,'""')+'"';const safe=s=>/^[=+@\-\t\r]/.test(String(s))?"'"+s:s;download('\uFEFF'+[['nama','jumlah','kelompok','telepon','hadir','kode','akad','vip'],...db.guests.filter(g=>!g.deleted).map(g=>[safe(g.name),g.quota,safe(g.group),g.phone||'',g.arrived,g.code,g.akad==='y'?'y':'n',g.vip==='y'?'y':'n'])].map(r=>r.map(quote).join(',')).join('\r\n'),'daftar-tamu.csv','text/csv;charset=utf-8');};
$('#import-csv').onclick=async()=>{if(await admin())$('#csv-file').click();};$('#csv-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Berkas maksimal 5 MB.');const rows=csvRows((await file.text()).replace(/^\uFEFF/,''));if(rows[0]?.slice(0,3).join(',').toLowerCase()!=='nama,jumlah,kelompok')throw Error('Kolom awal harus nama,jumlah,kelompok.');const phoneColumn=rows[0].findIndex(h=>h.trim().toLowerCase()==='telepon');const akadColumn=rows[0].findIndex(h=>h.trim().toLowerCase()==='akad');const vipColumn=rows[0].findIndex(h=>h.trim().toLowerCase()==='vip');const incoming=rows.slice(1).map((r,i)=>{const quota=Number(r[1]);if(!r[0]?.trim()||!Number.isInteger(quota)||quota<1||quota>1000)throw Error('Periksa nama dan jumlah pada baris '+(i+2));const akad=akadColumn<0?'n':(r[akadColumn]||'n').trim().toLowerCase();if(!['y','n'].includes(akad))throw Error('Kolom akad harus y/n pada baris '+(i+2));const vip=vipColumn<0?'n':(r[vipColumn]||'n').trim().toLowerCase();if(!['y','n'].includes(vip))throw Error('Kolom vip harus y/n pada baris '+(i+2));return{id:crypto.randomUUID(),code:crypto.randomUUID(),akad,vip,name:r[0].trim(),quota,group:r[2]||'',phone:TemuInvitations.normalizePhone(phoneColumn<0?'':r[phoneColumn]),active:true,arrived:0};});const seen=new Set(db.guests.map(g=>g.name.toLowerCase()));let duplicates=0;incoming.forEach(g=>{if(seen.has(g.name.toLowerCase()))duplicates++;seen.add(g.name.toLowerCase());});modal('Pratinjau impor',`<p>${incoming.length} undangan siap ditambahkan. ${duplicates} nama sama perlu diperiksa. Semua baris dibuat sebagai undangan baru.</p><ul>${incoming.slice(0,8).map(g=>`<li>${esc(g.name)} · ${g.quota} orang</li>`).join('')}</ul><button id="confirm-import" class="primary">Tambahkan ${incoming.length} undangan</button>`);$('#confirm-import').onclick=async()=>{try{await commit(d=>d.guests.push(...incoming));$('#modal').close();toast('Daftar tamu diimpor.');}catch(e){toast(e.message);}};}catch(e){toast(e.message);}finally{e.target.value='';}};
const b64=a=>btoa(Array.from(a,x=>String.fromCharCode(x)).join('')),unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function keyFor(pass,salt){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
$('#backup').onclick=async()=>{if(!await admin())return;try{const pass=$('#backup-pass').value;if(pass.length<8)throw Error('Kata sandi minimal 8 karakter.');const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},await keyFor(pass,salt),new TextEncoder().encode(JSON.stringify(db)));download(JSON.stringify({format:'temu-encrypted-v1',salt:b64(salt),iv:b64(iv),data:b64(new Uint8Array(encrypted))}),'temu-cadangan-'+new Date().toISOString().slice(0,10)+'.json','application/json');$('#backup-pass').value='';toast('Cadangan terenkripsi dibuat. Simpan kata sandinya.');}catch(e){toast(e.message);}};
$('#restore').onclick=async()=>{if(await admin())$('#backup-file').click();};$('#backup-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>15000000)throw Error('Cadangan terlalu besar.');const a=JSON.parse(await f.text());if(a.format!=='temu-encrypted-v1')throw Error('Format cadangan tidak sesuai.');const pass=$('#backup-pass').value;let data;try{data=validate(JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(a.iv)},await keyFor(pass,unb64(a.salt)),unb64(a.data)))));}catch{throw Error('Kata sandi salah atau cadangan rusak.');}modal('Pulihkan cadangan',`<p><strong>${esc(data.event.name)}</strong><br>${data.guests.length} undangan · ${data.guests.reduce((s,g)=>s+g.arrived,0)} orang hadir.</p><p>Data saat ini akan diganti. Buat cadangan terlebih dahulu jika masih diperlukan.</p><button id="confirm-restore" class="primary">Ganti dengan cadangan ini</button>`);$('#confirm-restore').onclick=async()=>{try{const restored=await TemuStore.replace(data,validate);db=restored.state;readFailed=false;unlocked=!db.pin;refreshSyncStatus(restored);scheduleSync();$('#modal').close();$('#backup-pass').value='';render();page('pindai');toast('Cadangan dipulihkan.');}catch(e){toast(e.message);}};}catch(e){toast(e.message);}finally{e.target.value='';}};
$('#persist').onclick=async()=>{const ok=await navigator.storage?.persist?.();toast(ok?'Perlindungan penyimpanan diaktifkan.':'Browser belum memberikan perlindungan. Tetap buat cadangan.');};
if('serviceWorker'in navigator){navigator.serviceWorker.register('sw.js?v=20261002-1').then(()=>navigator.serviceWorker.ready).then(()=>{const channel=new MessageChannel();channel.port1.onmessage=e=>{if(e.data.ready){$('#offline').textContent='✓ Siap digunakan offline';$('#offline-detail').textContent='Aplikasi dan pemindai tersimpan di perangkat. Uji dengan mode pesawat sebelum acara.';}};navigator.serviceWorker.ready.then(r=>r.active.postMessage('CHECK_CACHE',[channel.port2]));}).catch(()=>{$('#offline').textContent='Offline belum siap';$('#offline-detail').textContent='Akses melalui HTTPS atau localhost untuk menyiapkan penggunaan offline.';});}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'show_guest_search',description:'Buka daftar tamu dan isi pencarian nama, tanpa mencatat kehadiran.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:120}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.query!=='string'||input.query.length>120)throw Error('Pencarian tidak valid.');page('tamu');$('#search').value=input.query;renderGuests();return{opened:true};}});}catch{}}
