async function showWhatsApp(guest,invitationLink=null){
 const g=db.guests.find(x=>x.id===guest.id);if(!g?.active)return toast('Aktifkan undangan sebelum membagikannya.');
 if(!g.phone){
  modal('Nomor WhatsApp tamu',`<p>Tambahkan nomor WhatsApp untuk <strong>${esc(g.name)}</strong> agar pesan undangan dan QR dapat disiapkan.</p><form id="whatsapp-phone-form"><label for="whatsapp-phone">Nomor WhatsApp<input id="whatsapp-phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="30" placeholder="08… atau +62…" required></label><p class="hint">Nomor 08 akan disimpan dengan kode negara 62.</p><p id="whatsapp-phone-status" class="hint" role="status"></p><div class="actions"><button type="button" id="cancel-whatsapp-phone">Batal</button><button type="submit" class="primary">Simpan &amp; lanjutkan ke WhatsApp</button></div></form>`);
  $('#cancel-whatsapp-phone').onclick=()=>$('#modal').close();
  $('#whatsapp-phone-form').onsubmit=async event=>{
   event.preventDefault();const button=event.target.querySelector('button[type="submit"]');button.disabled=true;
   try{
    const phone=TemuInvitations.normalizePhone($('#whatsapp-phone').value);
    if(!phone)throw Error('Isi nomor WhatsApp tamu terlebih dahulu.');
    await commit(d=>{const guest=d.guests.find(x=>x.id===g.id);if(!guest?.active||guest.deleted)throw Error('Undangan sudah tidak aktif.');guest.phone=phone;});
    await showWhatsApp(db.guests.find(x=>x.id===g.id),invitationLink);
   }catch(error){$('#whatsapp-phone-status').textContent=error.message;}
   finally{button.disabled=false;}
  };
  return;
 }
 try{invitationLink=invitationLink||await guestInvitationURL(g);}catch(error){toast(error.message);return;}
 const event=structuredClone(db.event),code=g.code,phone=g.phone;
 const publicLink=invitationLink;
 const draft=TemuInvitations.message(g,event)+'\n\nLihat undangan digital kami:\n'+publicLink;
 modal('Undangan untuk '+g.name,`<p>WhatsApp tujuan: <strong>+${esc(phone)}</strong></p><div class="qr-preview">${qrSVG(g)}</div><label for="whatsapp-text">Teks undangan</label><textarea id="whatsapp-text" rows="8" maxlength="4000">${esc(draft)}</textarea><p id="share-info" class="hint" role="status">Menyiapkan satu gambar QR…</p><div class="actions"><button id="download-png" class="primary" disabled>1. Unduh QR PNG</button><button id="open-whatsapp">2. Buka WhatsApp dengan teks</button><button id="copy-invite">Salin teks saja</button><button id="copy-qr-text" disabled>Salin teks + gambar QR</button><button id="copy-qr-only" disabled>Salin gambar QR saja</button><button id="mark-whatsapp-sent">Tandai sudah kirim</button></div><p class="hint">Salin teks + gambar QR, lalu tempel di WhatsApp. Jika WhatsApp hanya menempel gambar, gunakan Salin teks saja untuk mengisi caption. Alternatifnya, lampirkan PNG yang diunduh satu kali. Membuka chat belum berarti pesan terkirim.</p>`);
 const box=$('#whatsapp-text'),copyBoth=$('#copy-qr-text'),copyImage=$('#copy-qr-only'),downloadButton=$('#download-png'),info=$('#share-info');
 const current=()=>{const latest=db.guests.find(x=>x.id===g.id);if(db.event.id!==event.id||!latest?.active||latest.code!==code||latest.phone!==phone||invitationSnapshot(latest)!==invitationSnapshot(g)||JSON.stringify(db.event)!==JSON.stringify(event))throw Error('Undangan berubah. Tutup dan buka kembali sebelum mengirim.');if(!box.value.trim())throw Error('Isi teks undangan terlebih dahulu.');return box.value;};
 $('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(current());toast('Teks disalin. Tempelkan pada pesan WhatsApp.');}catch(e){box.focus();box.select();toast('Pilih dan salin teks undangan secara manual.');}};
 $('#mark-whatsapp-sent').onclick=async()=>{try{current();await markWhatsApp(g.id,'sent');info.textContent='Ditandai sudah kirim WhatsApp oleh pengelola.';}catch(error){toast(error.message);}};
 $('#open-whatsapp').onclick=async()=>{try{const url=TemuInvitations.whatsappURL(phone,current()),chat=window.open('about:blank','_blank');if(!chat)throw Error('Browser memblokir tab WhatsApp. Izinkan pop-up lalu coba lagi.');chat.opener=null;chat.location.href=url;await markWhatsApp(g.id,'opened');info.textContent='WhatsApp dibuka dengan teks. Tempel gambar QR yang disalin atau lampirkan PNG sekali. Setelah benar-benar mengirim, klik Tandai sudah kirim.';}catch(error){toast(error.message);}};
 try{
 const file=await TemuInvitations.qrFile(g,event);if($('#download-png')!==downloadButton)return;
 copyBoth.disabled=false;copyImage.disabled=false;copyBoth.onclick=async()=>{try{await TemuInvitations.copyQR(file,current());info.textContent='Teks dan satu gambar QR disalin tanpa path file. Tempel di WhatsApp; jika caption kosong, salin teks saja.';}catch(error){info.textContent=error.message;}};copyImage.onclick=async()=>{try{current();await TemuInvitations.copyQR(file);info.textContent='Satu gambar QR disalin. Tempel pada WhatsApp, lalu salin teks saja untuk caption.';}catch(error){info.textContent=error.message;}};downloadButton.disabled=false;downloadButton.onclick=()=>{try{current();download(file,file.name,'image/png');info.textContent='QR PNG diunduh. Buka WhatsApp dengan teks, lalu lampirkan gambar ini satu kali.';}catch(e){toast(e.message);}};
 info.textContent='QR siap. Salin teks + gambar QR, lalu buka WhatsApp dan tempel. Status: '+whatsappStatus(db.guests.find(x=>x.id===g.id));
 }catch(e){if($('#share-info')===info)info.textContent=e.message+' Tutup dan coba lagi.';}
}
